def flatten_cells(cells: list[list[Cell]]) -> list[Cell]:
    return [cell for row in cells for cell in row]


def encode_owner_rle(cells: list[list[Cell]]) -> list[int]:
    flat = flatten_cells(cells)
    if not flat:
        return []
    encoded: list[int] = []
    current_owner = flat[0].owner
    run_length = 0
    for cell in flat:
        if cell.owner == current_owner:
            run_length += 1
            continue
        encoded.extend([run_length, current_owner])
        current_owner = cell.owner
        run_length = 1
    encoded.extend([run_length, current_owner])
    return encoded


def encode_map_line(cells: list[list[Cell]]) -> str:
    owners = encode_owner_rle(cells)
    strengths = [cell.strength for cell in flatten_cells(cells)]
    return " ".join(str(piece) for piece in owners + strengths) + " "


def encode_productions(cells: list[list[Cell]]) -> str:
    productions = [cell.production for cell in flatten_cells(cells)]
    return " ".join(str(value) for value in productions) + " "


def replay_frame(cells: list[list[Cell]]) -> list[list[list[int]]]:
    return [[[cell.owner, cell.strength] for cell in row] for row in cells]


def replay_productions(cells: list[list[Cell]]) -> list[list[int]]:
