def read_line_with_timeout(proc: subprocess.Popen[str], timeout: float | None) -> tuple[str | None, int]:
    if proc.stdout is None:
        return None, 0
    if timeout is None:
        start = time.perf_counter()
        line = proc.stdout.readline()
        elapsed = int((time.perf_counter() - start) * 1000)
        return (line if line != "" else None), elapsed
    selector = selectors.DefaultSelector()
    selector.register(proc.stdout, selectors.EVENT_READ)
    start = time.perf_counter()
    events = selector.select(timeout)
    elapsed = int((time.perf_counter() - start) * 1000)
    selector.close()
    if not events:
        return None, elapsed
    line = proc.stdout.readline()
    if line == "":
        return None, elapsed
    return line, elapsed


def write_line(proc: subprocess.Popen[str], line: str) -> bool:
    if proc.stdin is None:
        return False
    try:
        proc.stdin.write(line + "\n")
        proc.stdin.flush()
        return True
    except (BrokenPipeError, OSError):
        return False


def destroy_bot(proc: subprocess.Popen[str] | None) -> None:
    if proc is None:
        return
    if proc.poll() is not None:
        return
    try:
        proc.terminate()
        proc.wait(timeout=0.2)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass


def parse_move_line(raw_line: str, width: int, height: int, owner_map: list[list[Cell]], player_id: int) -> tuple[list[list[int]] | None, str | None]:
    stripped = raw_line.rstrip("\n")
    if any(ch not in "0123456789 " for ch in stripped):
        return None, stripped
    parts = stripped.split()
    if len(parts) % 3 != 0:
        return None, stripped
    directions = [[0 for _ in row] for row in owner_map]
    for index in range(0, len(parts), 3):
        try:
            x = int(parts[index])
            y = int(parts[index + 1])
            direction = int(parts[index + 2])
        except ValueError:
            return None, stripped
        if direction not in (0, 1, 2, 3, 4):
            return None, stripped
        if not (0 <= x < width and 0 <= y < height):
            continue
        if owner_map[y][x].owner != player_id:
            continue
        directions[y][x] = direction
    return directions, stripped


def direction_target(x: int, y: int, width: int, height: int, direction: int) -> tuple[int, int]:
    if direction == 1:
        return x, (y - 1) % height

        return x, (y - 1) % height
    if direction == 2:
        return (x + 1) % width, y
    if direction == 3:
        return x, (y + 1) % height
    if direction == 4:
        return (x - 1) % width, y
    return x, y


def neighborhood(x: int, y: int, width: int, height: int) -> Iterable[tuple[int, int]]:
    yield x, y
    yield x, (y - 1) % height
    yield (x + 1) % width, y
    yield x, (y + 1) % height
    yield (x - 1) % width, y


def resolve_turn(
    cells: list[list[Cell]],
    move_grids: dict[int, list[list[int]]],
    active_players: set[int],
) -> tuple[list[list[Cell]], list[list[int]]]:
    height = len(cells)
    width = len(cells[0])
    contributions: list[list[dict[int, int]]] = [[{} for _ in range(width)] for _ in range(height)]
    anchor_owner = [[cell.owner for cell in row] for row in cells]
    anchor_had_unit = [[False for _ in range(width)] for _ in range(height)]
    stayed_owner = [[0 for _ in range(width)] for _ in range(height)]
    replay_moves = [[0 for _ in range(width)] for _ in range(height)]

    for y in range(height):
        for x in range(width):
            cell = cells[y][x]
            if cell.owner == 0:
                contributions[y][x][0] = contributions[y][x].get(0, 0) + cell.strength
                anchor_had_unit[y][x] = True
                continue
            move_grid = move_grids.get(cell.owner)
            direction = 0 if move_grid is None else move_grid[y][x]
            replay_moves[y][x] = direction
            if direction == 0 or cell.owner not in active_players:
                contributions[y][x][cell.owner] = contributions[y][x].get(cell.owner, 0) + cell.strength
                anchor_had_unit[y][x] = True
                stayed_owner[y][x] = cell.owner
                continue
            tx, ty = direction_target(x, y, width, height, direction)
            contributions[ty][tx][cell.owner] = contributions[ty][tx].get(cell.owner, 0) + cell.strength

    adjacent_player_damage: list[list[dict[int, int]]] = [[{} for _ in range(width)] for _ in range(height)]
    for y in range(height):
        for x in range(width):
            for owner, strength in contributions[y][x].items():
                if owner == 0 or strength <= 0:
                    continue
                for nx, ny in neighborhood(x, y, width, height):
                    if nx == x and ny == y:
                        continue
                    bucket = damage[ny][nx]
                    bucket[owner] = bucket.get(owner, 0) + strength

    next_cells: list[list[Cell]] = []
    for y in range(height):
        row: list[Cell] = []
        for x in range(width):
            incoming = contributions[y][x]
            survivors: dict[int, int] = {}
            for owner, strength in incoming.items():
                enemy_damage = 0
                for other_owner, total in incoming.items():
                    if other_owner == owner:
                        continue
                    enemy_damage += total
                if owner != 0:
                    for other_owner, total in adjacent_player_damage[y][x].items():
                        if other_owner == owner:
                            continue
                        enemy_damage += total
                remaining = max(0, strength - enemy_damage)
                if remaining > 0:
                    survivors[owner] = remaining

            production = cells[y][x].production
            if survivors:
                owner, strength = max(survivors.items(), key=lambda item: (item[1], item[0]))
            else:
                owner = anchor_owner[y][x]
                strength = 0
                if owner != 0 and not anchor_had_unit[y][x]:
                    enemy_damage = 0
                    for other_owner, total in incoming.items():
                        if other_owner == owner:
                            continue
                        enemy_damage += total
                    for other_owner, total in adjacent_player_damage[y][x].items():
                        if other_owner == owner:
                            continue
                        enemy_damage += total
                    if enemy_damage > 0:
                        owner = 0
            if owner != 0 and owner == stayed_owner[y][x]:
                strength = min(255, strength + production)
            else:
                strength = min(255, strength)
            row.append(Cell(owner=owner, strength=strength, production=production))
        next_cells.append(row)
    return next_cells, replay_moves


def owned_players(cells: list[list[Cell]]) -> set[int]:
    result: set[int] = set()
    for cell in flatten_cells(cells):
        if cell.owner != 0:
            result.add(cell.owner)
    return result


def neutralize_player(cells: list[list[Cell]], player_id: int) -> None:
    for cell in flatten_cells(cells):
        if cell.owner == player_id:
            cell.owner = 0


def write_log(path: Path, bot: BotState) -> None:
    lines = [" --- Init ---", bot.name]
    if bot.response_log:
        lines.append(" --- Bot used 0 milliseconds ---")
        lines.append("-----------------------------------------------------------------------------")
    for frame, response, _ms in bot.response_log:
        lines.append(f" --- Frame #{frame} ---")
        lines.append("" if response is None else response)
        lines.append(" --- Bot used 0 milliseconds ---")
    if bot.error is not None:
        lines.append("ERRORED!")
        if bot.error.response is None:
            lines.append("No response received.")
        else:
            lines.append("Response received (if any):")
            lines.append(bot.error.response)
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


